export function DisclosureExample() {
  const {open, toggle} = useDisclosure();
  return <><button onClick={toggle} aria-expanded={open}>Travel details</button><p hidden={!open}>Bali · 10–15 November</p></>;
}

export function ControllableExample() {
  const [value, setValue] = useControllableState<string>(undefined, "Aarav Sharma");
  return <label>Traveler name<input value={value} onChange={event => setValue(event.target.value)} /></label>;
}

export function MediaQueryExample() {
  const compact = useMediaQuery("(max-width: 620px)");
  return <p>{compact ? "Phone layout" : "Wide layout"}</p>;
}

export function ThemeExample() {
  const {theme, setTheme} = useTheme();
  return <button disabled={!setTheme} onClick={() => setTheme?.(theme === "light" ? "dark" : "light")}>Current theme: {theme}</button>;
}
